CREATE TABLE IF NOT EXISTS "procurewise"."pmr_historical_records" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "recordKey" varchar(80) NOT NULL UNIQUE,
  "sourceWorkbook" varchar(255) NOT NULL,
  "sourceRow" integer NOT NULL,
  "fiscalYear" integer NOT NULL,
  "month" varchar(24),
  "endUser" varchar(180),
  "positionDesignation" varchar(180),
  "fundCode" varchar(80),
  "fundClass" varchar(80),
  "prNumber" varchar(80) NOT NULL,
  "modality" varchar(120),
  "item" text,
  "quantity" numeric(14,3),
  "unitOfIssue" varchar(60),
  "unitBudget" numeric(14,2),
  "estimatedTotal" numeric(14,2),
  "unitLcrb" numeric(14,2),
  "total" numeric(14,2),
  "purpose" text,
  "office" varchar(180),
  "lonReceivedDate" varchar(80),
  "bacAwardApprovedDate" varchar(80),
  "poContractDate" varchar(80),
  "poContractDateReceived" varchar(80),
  "deliveryDate" varchar(80),
  "supplier" varchar(240),
  "iarDate" varchar(80),
  "sectionCodeDepartment" varchar(120),
  "releasedDate" varchar(80),
  "status" varchar(80),
  "remarks" text,
  "obrNumber" varchar(120),
  "rfqsPrinted" varchar(80),
  "salesChargeInvoice" varchar(160),
  "importedAt" timestamp NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "pmr_history_year_idx" ON "procurewise"."pmr_historical_records" USING btree ("fiscalYear");
CREATE INDEX IF NOT EXISTS "pmr_history_pr_idx" ON "procurewise"."pmr_historical_records" USING btree ("prNumber");
CREATE INDEX IF NOT EXISTS "pmr_history_supplier_idx" ON "procurewise"."pmr_historical_records" USING btree ("supplier");
